document.addEventListener('DOMContentLoaded',()=>{const grid=document.getElementById('categoriesGridBody');const modal=document.getElementById('categoryModal');const modalTitle=document.getElementById('categoryModalTitle');const modalError=document.getElementById('categoryModalError');const form=document.getElementById('categoryForm');const nameInput=document.getElementById('categoryName');const iconSelect=document.getElementById('categoryIcon');const colorSelect=document.getElementById('categoryColor');const preview=document.getElementById('categoryPreview');const previewIcon=preview?.querySelector('i');const addBtn=document.getElementById('addCategoryBtn');const cancelBtn=document.getElementById('categoryModalCancel');const csrfToken=document.querySelector('meta[name="csrf-token"]')?.content;if(!modal||!form)return;let editingId=null;const COLOR_CLASSES=['cat-navy','cat-teal','cat-green','cat-rose','cat-purple','cat-brown','cat-gold'];function updatePreview(){if(!preview||!previewIcon)return;COLOR_CLASSES.forEach(c=>preview.classList.remove(c));preview.classList.add(colorSelect.value);previewIcon.className=`fa-solid ${iconSelect.value}`}
function showError(message){if(!modalError)return;modalError.textContent=message;modalError.hidden=!1}
function hideError(){if(!modalError)return;modalError.hidden=!0}
function openModal(title){modalTitle.textContent=title;hideError();modal.classList.add('open')}
function closeModal(){modal.classList.remove('open');editingId=null}
addBtn?.addEventListener('click',()=>{editingId=null;form.reset();updatePreview();openModal('إضافة تصنيف جديد');nameInput?.focus()});grid?.addEventListener('click',(e)=>{const editBtn=e.target.closest('[data-cat-edit-trigger]');if(!editBtn)return;const card=editBtn.closest('.admin-category-card');if(!card)return;editingId=card.dataset.catId;nameInput.value=card.dataset.catName||'';iconSelect.value=card.dataset.catIcon||'fa-book';colorSelect.value=card.dataset.catColor||'cat-navy';updatePreview();openModal('تعديل التصنيف')});iconSelect?.addEventListener('change',updatePreview);colorSelect?.addEventListener('change',updatePreview);cancelBtn?.addEventListener('click',closeModal);modal.addEventListener('click',(e)=>{if(e.target===modal)closeModal();});document.addEventListener('keydown',(e)=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeModal();});form.addEventListener('submit',async(e)=>{e.preventDefault();const name=nameInput.value.trim();if(!name)return;const submitBtn=form.querySelector('button[type="submit"]');submitBtn.disabled=!0;hideError();const url=editingId?`/admin/categories/${editingId}`:'/admin/categories';const method=editingId?'PUT':'POST';try{const response=await fetch(url,{method,headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':csrfToken,},body:JSON.stringify({name,icon:iconSelect.value,color:colorSelect.value,}),});if(!response.ok){const data=await response.json().catch(()=>({}));const message=data.errors?Object.values(data.errors).flat().join(' '):(data.message||'حدث خطأ، حاول مرة أخرى');showError(message);return}
window.location.reload()}catch(err){showError('تعذر الاتصال بالخادم، حاول مرة أخرى')}finally{submitBtn.disabled=!1}})})